export default function TransactionsScreen() {
  const { transactions, categories, accounts, filters, updateFilters, clearFilters, loading, refreshing, loadingMore, error, refresh, loadMore, filteredTotal, totals } = useFinanceTransactions(50);
  const categoryMap = useMemo(() => new Map(categories.map((cat) => [cat.id, cat.name])), [categories]);
  const sources = useMemo(() => Array.from(new Set(transactions.map((tx) => tx.provider || tx.source || 'manual'))).sort(), [transactions]);
  const hasFilters = filters.type !== 'all' || filters.categoryId !== 'all' || filters.source !== 'all' || filters.minAmount !== '' || filters.maxAmount !== '' || filters.startDate !== '' || filters.endDate !== '' || filters.search !== '';

  if (loading && transactions.length === 0) return <ScrollView className="flex-1 bg-background" contentContainerStyle={{ flexGrow: 1 }}><View className="flex-1 items-center justify-center px-8"><ActivityIndicator size="large" /><Text size="sm" className="mt-3 text-muted-foreground">Loading transactions...</Text></View></ScrollView>;

  return (
    <ScrollView className="flex-1 bg-background" contentContainerStyle={{ paddingBottom: 32 }} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} />}>
      <View className="gap-4 px-5 pt-14">
        <View><Text size="sm" className="text-muted-foreground">Finance · Transactions</Text><Heading size="xl" className="mt-1">Transactions</Heading><Text size="sm" className="mt-1 text-muted-foreground">{filteredTotal} matching transactions · showing {transactions.length}</Text></View>
        {error ? <Card className="border border-destructive/30 p-4"><Text className="font-semibold text-destructive">Finance data could not be loaded</Text><Text size="sm" className="mt-1 text-muted-foreground">{error}</Text><Button className="mt-3" size="sm" onPress={() => void refresh()}><ButtonText>Retry</ButtonText></Button></Card> : null}
        <Card className="w-full p-4"><View className="flex-row gap-3"><View className="flex-1 rounded-xl bg-muted p-3"><Text size="xs" className="text-muted-foreground">Income</Text><Text size="md" className="mt-1 font-semibold text-green-600">+{formatCurrency(totals.income)}</Text></View><View className="flex-1 rounded-xl bg-muted p-3"><Text size="xs" className="text-muted-foreground">Expenses</Text><Text size="md" className="mt-1 font-semibold text-red-600">-{formatCurrency(totals.expenses)}</Text></View><View className="flex-1 rounded-xl bg-muted p-3"><Text size="xs" className="text-muted-foreground">Net</Text><Text size="md" className="mt-1 font-semibold">{totals.net >= 0 ? '+' : '-'}{formatCurrency(Math.abs(totals.net))}</Text></View></View></Card>
        <Input><InputField placeholder="Search merchant, note, reference..." value={filters.search} onChangeText={(search) => updateFilters({ search })} /></Input>
        <View className="flex-row flex-wrap gap-2">{(['all', 'income', 'expense', 'transfer'] as const).map((type) => <Button key={type} variant={filters.type === type ? 'default' : 'outline'} size="sm" onPress={() => updateFilters({ type })}><ButtonText>{type === 'all' ? 'All' : type[0].toUpperCase() + type.slice(1)}</ButtonText></Button>)}</View>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}><View className="flex-row gap-2"><Button variant={filters.source === 'all' ? 'secondary' : 'ghost'} size="sm" onPress={() => updateFilters({ source: 'all' })}><ButtonText>All sources</ButtonText></Button>{sources.map((source) => <Button key={source} variant={filters.source === source ? 'secondary' : 'ghost'} size="sm" onPress={() => updateFilters({ source })}><ButtonText>{source.replace(/_/g, ' ')}</ButtonText></Button>)}</View></ScrollView>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}><View className="flex-row gap-2"><Button variant={filters.categoryId === 'all' ? 'secondary' : 'ghost'} size="sm" onPress={() => updateFilters({ categoryId: 'all' })}><ButtonText>All categories</ButtonText></Button>{categories.map((category) => <Button key={category.id} variant={filters.categoryId === category.id ? 'secondary' : 'ghost'} size="sm" onPress={() => updateFilters({ categoryId: category.id })}><ButtonText>{category.name}</ButtonText></Button>)}</View></ScrollView>
        <View className="flex-row gap-2"><Input className="flex-1"><InputField placeholder="Min ₹" value={filters.minAmount} onChangeText={(minAmount) => updateFilters({ minAmount })} keyboardType="decimal-pad" /></Input><Input className="flex-1"><InputField placeholder="Max ₹" value={filters.maxAmount} onChangeText={(maxAmount) => updateFilters({ maxAmount })} keyboardType="decimal-pad" /></Input></View>
        <View className="flex-row gap-2"><Input className="flex-1"><InputField placeholder="Start YYYY-MM-DD" value={filters.startDate} onChangeText={(startDate) => updateFilters({ startDate })} /></Input><Input className="flex-1"><InputField placeholder="End YYYY-MM-DD" value={filters.endDate} onChangeText={(endDate) => updateFilters({ endDate })} /></Input></View>
        {hasFilters ? <Button variant="ghost" size="sm" onPress={clearFilters}><ButtonText>Clear all filters</ButtonText></Button> : null}
        {filteredTotal === 0 ? <Card className="p-6"><Text className="text-center font-semibold">{hasFilters ? 'No transactions match these filters' : 'No transactions yet'}</Text><Text size="sm" className="mt-1 text-center text-muted-foreground">{hasFilters ? 'Try widening the amount or date range, or clearing a filter.' : 'Add an expense, income, transfer, or import a statement to get started.'}</Text></Card> : <View className="gap-2">{transactions.map((tx) => <TransactionItem key={tx.id} transaction={tx} categoryName={categoryMap.get(tx.categoryId) || 'Uncategorized'} accounts={accounts} />)}{loadingMore ? <ActivityIndicator className="py-4" /> : null}{transactions.length < filteredTotal ? <Button variant="outline" className="mt-2" onPress={() => void loadMore()} disabled={loadingMore}><ButtonText>{loadingMore ? 'Loading...' : 'Load more transactions'}</ButtonText></Button> : null}</View>}
      </View>
    </ScrollView>
  );
}
